class DatVacacionesVariables extends BaseDatVacacionesVariables {

    /**
     * Obtener todas las variables de vacaciones.
     * 
     * @return array    Listado de los datos de las variables de vacaciones.
     */
    public static function obtenerTodasVariables() {

        //Devolviendo el listado de las variables de vacaciones en forma de arreglo.
        return Doctrine_Query::create()
                ->from('DatVacacionesVariables')
                ->fetchArray();
    }
    
    public function obtenerConfAcumulacionLiquidacion(){
		$sql = "select *  from mod_nomina.dat_vacacionesvariables;";
		$mg = Doctrine_Manager::getInstance();
		$conn = $mg->getCurrentConnection();
		return $conn->fetchAll($sql);
	}
	
    public function obtenerVariablesAcumulacionLiquidacion(){
		$sql = "select dv.*,  conf.denominacion as denomreporte, var.denominacion as denomvarreporte
					from mod_nomina.dat_variablesformulavacacionesvariables dv
					left join mod_nomina.conf_tiporeportescertificaciones conf on (conf.idconfreportescertificaciones = dv.idconfreportescertificaciones)
					left join mod_nomina.conf_variablestiporeportescertificaciones var on (var.idvariablesconfreportescertificaciones = dv.idvariablesconfreportescertificaciones)
					;";
		$mg = Doctrine_Manager::getInstance();
		$conn = $mg->getCurrentConnection();
		return $conn->fetchAll($sql);
	}
}
